def is_anagram(s: str, t: str) -> bool:
    """Return True if s and t are anagrams (case-insensitive, ignore spaces)."""

    # Convert strings to lower case and remove spaces
    s = s.lower().replace(" ", "")
    t = t.lower().replace(" ", "")

    # Early return if lengths differ
    if len(s) != len(t):
        return False

    # Use a dictionary to count occurrences of each character
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in t:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    # Check if all counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True

