def alien_order(words: list) -> str:
    from collections import defaultdict, deque

    # Helper function to build graph and indegree count
    def build_graph(words):
        graph = defaultdict(list)
        indegree = {}
        chars = set()

        for word in words:
            for char in word:
                chars.add(char)

        for i in range(len(words) - 1):
            word1, word2 = words[i], words[i + 1]
            min_len = min(len(word1), len(word2))

            for j in range(min_len):
                if word1[j] != word2[j]:
                    graph[word1[j]].append(word2[j])
                    indegree[word2[j]] = indegree.get(word2[j], 0) + 1
                    break

        for char in chars:
            if char not in indegree:
                indegree[char] = 0

        return graph, indegree, chars

    if not words:
        return ""

    graph, indegree, chars = build_graph(words)

    # Kahn's algorithm for topological sorting
    result = []
    queue = deque([char for char in chars if indegree[char] == 0])

    while queue:
        char = queue.popleft()
        result.append(char)

        for neighbor in graph[char]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

