def get_skyline(buildings: list) -> list:
    events = []
    for left, right, height in buildings:
        events.append((left, -height))  # negative height for start events
        events.append((right, height))  # positive height for end events
    events.sort()

    prev_height = 0
    result = []
    heap = [(0, float('inf'))]  # use a min heap to track the max height
    for pos, height in events:
        if height < 0:
            height = -height
            heap.append((height, pos))  # add the height to the heap
        else:
            heap.remove((height, pos))  # remove the height from the heap

        curr_height = -heap[0][0]  # the max height in the heap
        if curr_height != prev_height:
            result.append([pos, curr_height])
            prev_height = curr_height

    return result

