def serialize_tree(root) -> str:
    if not root:
        return "null"

    queue = deque([root])
    result = []

    while queue:
        current = queue.popleft()
        if current:
            result.append(str(current.val))
            queue.append(current.left)
            queue.append(current.right)
        else:
            result.append("null")

    # Remove trailing 'null' values
    while result and result[-1] == "null":
        result.pop()

    return ",".join(result)

