def parse_bool_expr(expression: str) -> bool:
    import re

    def eval_expr(expr: str) -> bool:
        if expr == 't':
            return True
        elif expr == 'f':
            return False
        else:
            raise ValueError("Invalid expression")

    def apply_op(op: str, left: bool, right: bool) -> bool:
        if op == '!':
            return not left
        elif op == '&':
            return left and right
        elif op == '|':
            return left or right
        else:
            raise ValueError("Invalid operator")

    # Remove spaces and replace '!' with ' not '
    expression = expression.replace(' ', '')
    expression = re.sub(r'(!)([tf])', r' not \2', expression)

    # Evaluate the expression
    stack = []
    i = 0
    while i < len(expression):
        if expression[i] in ('t', 'f'):
            stack.append(eval_expr(expression[i:i+2]))
            i += 2
        elif expression[i] in ('!', '&', '|'):
            right = stack.pop()
            left = stack.pop() if stack else eval_expr(expression[i-2:i])
            stack.append(apply_op(expression[i], left, right))
            i += 1
        else:
            i += 1

    return stack[0]

