        for char in group:
            if char == '{':
                stack.append(cur)
                cur = ''
            elif char == '}':
                prev = stack.pop()
                prev += cur
                cur = expand_group(prev)
            else:
                cur += char
        return [x for y in cur for x in expand_group(y)]

