def count_xor_subsets(nums: list, target: int) -> int:
    n = len(nums)
    dp = [0] * (target + 1)
    dp[0] = 1

    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] += dp[j - num]

    return dp[target] - 1 if nums else 0

def count_xor_subsets(nums: list, target: int) -> int:
    if not nums:
        return 0

    n = len(nums)
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(target + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] += dp[i - 1][j - nums[i - 1]]

    return dp[n][target]

def count_xor_subsets(nums: list, target: int) -> int:
    def dfs(index, current_xor):
        if index == len(nums):
            return int(current_xor == target)
        return dfs(index + 1, current_xor) + dfs(index + 1, current_xor ^ nums[index])

    return dfs(0, 0) - 1

