def count_xor_subsets(nums: list, target: int) -> int:
    def subset_xor(start, current_xor):
        if start == len(nums):
            return 1 if current_xor == target else 0
        include = subset_xor(start + 1, current_xor ^ nums[start])
        exclude = subset_xor(start + 1, current_xor)
        return include + exclude

    return subset_xor(0, 0) - 1  # Subtract 1 to exclude the empty subset

def count_xor_subsets(nums: list, target: int) -> int:
