    dp = [0] * (target + 1)
    dp[0] = 1  # Base case: empty subset

    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] += dp[j - num]

    return dp[target] - 1  # Subtract 1 to exclude the empty subset

