def find_min_steps_zuma(board: str, hand: str) -> int:
    def remove_groups(s: str) -> (str, int):
        i, n, cnt = 0, len(s), Counter()
        while i < n:
            j = i
            while j < n and s[i] == s[j]:
                j += 1
            if j - i >= 3:
                cnt[s[i]] += j - i
                i = j
            else:
                i += 1
        res = ''
        for i in range(n):
            if s[i] not in cnt or cnt[s[i]] == 0:
                res += s[i]
                cnt[s[i]] -= 1
        return res, sum(cnt.values())

    def dfs(board: str, hand: str, memo) -> int:
        if board in memo:
            return memo[board]
        if not board:
            return 0
        res = float('inf')
        for i in range(len(board)):
            for j in range(len(hand)):
                new_board = board[:i] + hand[j] + board[i:]
                new_board, removed = remove_groups(new_board)
                if removed:
                    res = min(res, 1 + dfs(new_board, hand, memo))
        memo[board] = res if res != float('inf') else -1
        return memo[board]

    memo = {}
    return dfs(board, hand, memo)

def find_min_steps_zuma(board: str, hand: str) -> int:
