        for char in s:
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        return ''.join(stack)

    def dfs(board: str, hand: str, memo) -> int:
        if board in memo:
            return memo[board]
        if not board:
            return 0

        min_steps = float('inf')
