            for j in range(len(board) + 1):
                new_board = board[:j] + hand[i] + board[j:]
                new_board = remove_groups(new_board)
                steps = 1 + dfs(new_board, hand[:i] + hand[i+1:], memo)
                min_steps = min(min_steps, steps)

        memo[board] = min_steps if min_steps != float('inf') else -1
        return memo[board]

    memo = {}
    result = dfs(board, hand, memo)
    return result

