def find_min_steps_zuma(board: str, hand: str) -> int:
    def remove_groups(s: str) -> (str, int):
        i, n, cnt = 0, len(s), Counter()
        while i < n:
            j = i
            while j < n and s[i] == s[j]:
                j += 1
            if j - i >= 3:
                cnt[s[i]] += j - i
                i = j
            else:
                i += 1
        return ''.join([c * (n // 3) for c in sorted(cnt, key=lambda x: -cnt[x])]), sum(cnt.values())

    def dfs(board: str, hand: Counter) -> int:
        if not board:
            return 0
        res = float('inf')
        for i in range(len(board)):
            for j in range(i + 1, len(board) + 1):
                if len(board[i:j]) >= 3:
                    new_hand = hand.copy()
                    for c in board[i:j]:
                        new_hand[c] -= 1
                    new_board, removed = remove_groups(board[:i] + board[j:])
                    res = min(res, removed + dfs(new_board, new_hand))
        return res if res != float('inf') else -1

    hand_counter = Counter(hand)
    return dfs(board, hand_counter)

def find_min_steps_zuma(board: str, hand: str) -> int:
    from collections import Counter

    def remove_groups(s: str) -> (str, int):
        groups = []
        i = 0
        while i < len(s):
            count = 1
            while i + count < len(s) and s[i] == s[i + count]:
                count += 1
            if count >= 3:
                groups.append((s[i], count))
            i += count
        for color, count in groups:
            s = s.replace(color * count, '', 1)
        return s, len(groups)

    def explore(board: str, hand: Counter, steps: int) -> int:
        if not board:
            return steps
        if steps >= len(hand) + 1:
            return float('inf')
        min_steps = float('inf')
        for i in range(len(board)):
            for j in range(len(board) + 1):
                new_board = board[:i] + board[j:]
                for color, count in hand.items():
                    if count > 0:
                        new_hand = hand.copy()
                        new_hand[color] -= 1
                        new_board, removed = remove_groups(new_board)
                        while removed > 0:
                            removed = remove_groups(new_board)[1]
                        min_steps = min(min_steps, explore(new_board, new_hand, steps + 1))
        return min_steps

    hand = Counter(hand)
    result = explore(board, hand, 0)
    return result if result != float('inf') else -1

