def find_min_steps_zuma(board: str, hand: str) -> int:
    def clear(board: str) -> str:
        while True:
            prev_board = board
            board = ''.join([''.join(k*v for k, v in group) for group in
                             (''.join(board).replace('RGB', ' ').replace('RBG', ' ').replace('GBR', ' ').replace('GRB', ' ').replace('BGR', ' ').replace('BRG', ' ').split())])
            if prev_board == board:
                break
        return board

    def dfs(board: str, hand: str, steps: int, cache) -> int:
        if board in cache:
            return cache[board]
        if not board:
            return steps
        min_steps = float('inf')
        for i in range(len(board)):
            for j in range(len(hand)):
                new_board = board[:i] + hand[j] + board[i:]
                cleared_board = clear(new_board)
                if len(cleared_board) < len(board):
                    min_steps = min(min_steps, dfs(cleared_board, hand[:j] + hand[j+1:], steps + 1, cache))
        cache[board] = min_steps if min_steps != float('inf') else -1
        return cache[board]

    cache = {}
    return dfs(board, hand, 0, cache)

