        groups = [tuple(g) for _, g in itertools.groupby(s)]
        removed = True
        while removed:
            removed = False
            for group in groups:
                if len(group) >= 3:
                    s = s.replace(group, '', 1)
                    groups = [tuple(g) for _, g in itertools.groupby(s)]
                    removed = True
                    break
        return s

    def dfs(board: str, hand: str) -> int:
